		'mac and cheese': 5stars
		'cereal': 2stars
		'gruel': 1stars
	}
موردعلاقه‌ها{'حریره'}\

\['سیب' 'زردآلو' 'موز'].صافی(
	ƒ(واژه•'') واژه.حروفکوچک().آغازمی‌شود('الف')
)\

\['گربه' 'سگ' 'موش' 'موش' 'اسب‌چه'].تا(
	ƒ(حیوان•'') حیوان = 'rat'
)\🪲

\['گربه' 'سگ' 'موش' 'موش' 'اسب‌چه'].پیداکردن(
	ƒ(حیوان•'') حیوان.دارد('ای')
)\🪲

\['آدا لاولیس' 'گریس هاپر' 'آلن تورینگ'].مرتب‌شده(
	ƒ(نام2•'') (نام2 ÷ ' ').آخر()
)\

\{'amy': 0points 'jen': 0points 'tony': 3points}.برداشتن(
	0points
)\

\{'amy': 0points 'jen': 0points 'tony': 3points}.صافی(
	ƒ(کلید2•'' ارزش2•#points) (کلید2 = 'amy') | (ارزش2 > 0points)
)\

\{'amy': 5points 'jen': 3points 'tony': 0points}.ترجمه‌کردن(
	ƒ(کلید2•'' ارزش2•#points) ارزش2 + 1points
)\🪲

\صحنه(
	خط‌دور('الف' "Noto Sans" 10m).ترجمه‌کردن(
		ƒ(اشاره2) عبارت('•' مکان: اشاره2)
	)
)\

\موسیقی(
	[
		آهنگ([1 2 3 5 3 2 1 ø] ساز: ساز.فلوت)
		آهنگ([{1𝅝 3 5} {5𝅝 7 9}] ساز: ساز.پیانو بلندیصدا: 50%)
	]
)\

\خانه: [1 3 5 3]
موسیقی(
	آهنگ(
		خانه
		.بافهرست(
			خانه.ترجمه‌کردن(ƒ(n2•#) n2 + 2)
		)
		.بافهرست(
			خانه.وارونه‌شده()
		)
		.بافهرست(
			خانه.ترجمه‌کردن(ƒ(n3•#) 8 - n3)
		)
		ساز: ساز.پیانو
	)
)\

\عبارت(
	'سلام'
	درحالاستراحت: دنباله(
		{0%: ژست(چرخش: 360°) 100%: ژست(چرخش: 0°)}
	)\🪲
